/**
 * @name Potential Path Traversal in Library
 * @description Detects flow from function parameters to file open operations, indicating potential path traversal if the input is not validated.
 * @kind path-problem
 * @problem.severity warning
 * @id py/library-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Consider parameters of functions in the package as sources
    exists(Function f |
      f.getScope().getEnclosingModule().getName().matches("importlib_metadata%") and
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sinks are arguments to open() or similar file operations
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "function parameter"
